import{_ as a,o,c as l,a2 as r}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"7.4 安全隔离变压器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-4-an-quan-ge-li-bian-ya-qi.md","filePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-4-an-quan-ge-li-bian-ya-qi.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-4-an-quan-ge-li-bian-ya-qi.md"};function e(n,t,s,d,h,u){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="_7-4-安全隔离变压器" tabindex="-1">7.4 安全隔离变压器 <a class="header-anchor" href="#_7-4-安全隔离变压器" aria-label="Permalink to &quot;7.4 安全隔离变压器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>3.3 节讲过&quot;安全电压必须由安全隔离变压器供电&quot;。这一节专门讲安全隔离变压器:它为什么能&quot;隔离危险&quot;,和普通变压器、自耦变压器有什么区别。</p><h2 id="一、安全隔离变压器的两大作用" tabindex="-1">一、安全隔离变压器的两大作用 <a class="header-anchor" href="#一、安全隔离变压器的两大作用" aria-label="Permalink to &quot;一、安全隔离变压器的两大作用&quot;">​</a></h2><p><strong>安全隔离变压器</strong>同时提供两种保护:</p><ol><li><strong>电气隔离</strong>:一次侧与二次侧之间<strong>没有直接电气连接</strong>,靠铁芯中的磁耦合传递能量。即使一次侧故障,高压也不会&quot;串&quot;到二次侧;</li><li><strong>安全电压</strong>:二次侧输出电压在<strong>安全电压等级</strong>(42/36/24/12/6 V)内,人接触不易触电。</li></ol><h2 id="二、为什么它比普通变压器-安全" tabindex="-1">二、为什么它比普通变压器&quot;安全&quot; <a class="header-anchor" href="#二、为什么它比普通变压器-安全" aria-label="Permalink to &quot;二、为什么它比普通变压器&quot;安全&quot;&quot;">​</a></h2><p>普通降压变压器二次侧通常要<strong>接地</strong>,且与一次侧共用系统;一旦一次侧绝缘损坏,故障可能波及二次侧。</p><p>安全隔离变压器的关键区别:</p><table tabindex="0"><thead><tr><th>对比</th><th>普通变压器</th><th>安全隔离变压器</th></tr></thead><tbody><tr><td>二次侧接地</td><td>通常接地</td><td><strong>不接地(浮地)或按规定处理</strong></td></tr><tr><td>电气隔离</td><td>较弱</td><td><strong>强(双绕组可靠隔离)</strong></td></tr><tr><td>输出电压</td><td>随用途</td><td><strong>限定在安全电压等级</strong></td></tr><tr><td>用途</td><td>配电</td><td>安全电压供电、检修电源</td></tr></tbody></table><blockquote><p>💡 通俗理解:隔离变压器把二次侧&quot;孤立&quot;起来,人即使单手碰到二次侧的带电部分,电流也难以经大地形成回路(因为二次侧不接地、浮地),触电风险大大降低。</p></blockquote><h2 id="三、严格禁止-自耦变压器不能当安全电源" tabindex="-1">三、严格禁止:自耦变压器不能当安全电源 <a class="header-anchor" href="#三、严格禁止-自耦变压器不能当安全电源" aria-label="Permalink to &quot;三、严格禁止:自耦变压器不能当安全电源&quot;">​</a></h2><p><strong>自耦变压器</strong>的一次、二次<strong>共用一组绕组</strong>,没有完全隔离:</p><ul><li>如果绕组故障、或中性线断开,高压可能<strong>直接串到低压侧</strong>;</li><li>所以<strong>严禁用自耦变压器作为安全电压的电源</strong>,否则&quot;安全电压&quot;形同虚设。</li></ul><blockquote><p>⚠️ 判断题高频:安全电压必须由<strong>隔离变压器(双绕组)<strong>供电,不能使用</strong>自耦变压器</strong>。</p></blockquote><h2 id="四、安全隔离变压器的应用" tabindex="-1">四、安全隔离变压器的应用 <a class="header-anchor" href="#四、安全隔离变压器的应用" aria-label="Permalink to &quot;四、安全隔离变压器的应用&quot;">​</a></h2><ul><li><strong>安全电压照明、行灯</strong>的供电电源(3.3 节的行灯、金属容器内照明);</li><li><strong>检修电源</strong>:电工检修时给手持电动工具、行灯供电;</li><li>医疗设备、特殊作业场所的供电。</li></ul><h2 id="五、使用要求" tabindex="-1">五、使用要求 <a class="header-anchor" href="#五、使用要求" aria-label="Permalink to &quot;五、使用要求&quot;">​</a></h2><ul><li>二次侧应按规定<strong>不接地</strong>(浮地)使用,保证隔离效果;</li><li>二次侧回路独立,不并入其他电源;</li><li>定期检查绕组绝缘,保证隔离可靠;</li><li>与一次侧之间要<strong>加强绝缘</strong>(双重绝缘或加强绝缘)。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 安全隔离变压器 = 电气隔离 + 安全电压。</li><li>✅ <strong>禁止用自耦变压器</strong>提供安全电压。</li><li>✅ 二次侧一般<strong>不接地</strong>(浮地)。</li><li>⚠️ 易混点:隔离变压器(安全电压电源)vs 自耦变压器(不能用于安全电源)。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>安全隔离变压器靠&quot;磁耦合、电隔离&quot;输出安全电压。</li><li>二次侧浮地、输出电压在安全电压等级内。</li><li>自耦变压器严禁作安全电压电源。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)安全电压应由安全隔离变压器供电。( )</li><li>(判断)可以用自耦变压器作为安全电压的电源。( )</li><li>(单选)安全隔离变压器的二次侧一般()。 A. 接地　B. 不接地(浮地)　C. 接零　D. 与一次侧相连</li><li>(判断)安全隔离变压器具有电气隔离作用,一次侧故障不会直接波及二次侧。( )</li><li>(单选)行灯等安全电压电源,应选用()。 A. 自耦变压器　B. 普通降压变压器　C. 安全隔离变压器　D. 调压器</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。安全电压必须由安全隔离变压器供电。</li><li><strong>×</strong>。严禁用自耦变压器作安全电压电源。</li><li><strong>B</strong>。二次侧不接地(浮地)才能实现隔离。</li><li><strong>√</strong>。靠磁耦合传递能量,电气上隔离。</li><li><strong>C</strong>。安全电压电源用安全隔离变压器。</li></ol></details>',26)])])}const q=a(i,[["render",e]]);export{c as __pageData,q as default};
